    // Gestion de fechas y de mostrar o no el faldon
    if (!areWeInDateRange(now)) {
        containerRtvePlayAlert.remove();
    } else if (!shouldShowBanner()) {
        if (!containerRtvePlayAlert.classList.contains('ghost')) {
            containerRtvePlayAlert.classList.add('ghost');
        }
    } else {
        const userAgent = navigator.userAgent;
        // Detect iOS (iPhone, iPod, iPad including iPadOS desktop mode) and Android
        const isIOS = /iPhone|iPod|iPad/i.test(userAgent) || (userAgent.includes("Mac") && "ontouchend" in document);
        const isAndroid = /Android/i.test(userAgent);

        containerRtvePlayAlert.classList.remove('ghost');

        // Auto-close if mobile OS detected OR viewport is small
        if (isIOS || isAndroid || window.innerWidth <= 1024) {
            setTimeout(closeBanner, AUTO_CLOSE_TIME);
        }
    }

    crossRtvePlayAlert.addEventListener('click', closeBanner);

    // Gestion de la cuenta atras
    if (daysCountDownElement !== null && hoursCountDownElement !== null) {
        if( navigator.userAgent.indexOf("AdobeAIR") < 0) { fn_cuentaAtras(); }

        // Si queda un dia
        if (daysCountDownElement.querySelector('#days').innerHTML === '1') {
            daysCountDownElement.querySelector('abbr').classList.add('singular-day')
        }

        // Si queda una hora
        if (hoursCountDownElement.querySelector('#hours').innerHTML === '1') {
            hoursCountDownElement.querySelector('abbr').classList.add('singular-hour')
        }
    }

    let url = window.location.href;
    let urlParams = new URLSearchParams(url);
    let viewParam = urlParams .get("view");
    if(viewParam === "negative"){
        document.getElementById("rtvePlayAlert").classList.add("negativeView");
    }
}"]

