["message","(evt) => {
                    if (evt.data.action && evt.origin && evt.origin.startsWith('https://')) {
                        const originUrl = new URL(evt.origin);
                        if (originUrl.hostname === 'stories.rtve.es' || originUrl.hostname.endsWith('besocy.news')) {
                            // NS_EMBED_STYLES
                            if (evt.data.action === 'NS_EMBED_STYLES' && evt.data.styles) {
                                const check = document.querySelector('style#NS_EMBED_STYLES');
                                if (!check) {
                                    const styles = document.createElement('style');
                                    styles.id = 'NS_EMBED_STYLES';
                                    styles.innerHTML = evt.data.styles;
                                    document.head.append(styles);
                                }
                            }
                            // NS_EMBED_INIT
                            else if (evt.data.action === 'NS_EMBED_INIT') {
                                const initBtn = document.querySelector('div.txtBox > a.butt');
                                initBtn && initBtn.click();
                            }
                            // NS_EMBED_PLAY
                            else if (evt.data.action === 'NS_EMBED_PLAY') {
                                const elementPlayer = document.getElementById('vjs_video_3');
                                elementPlayer && elementPlayer.player && elementPlayer.player.play();
                            }
                            // NS_EMBED_PAUSE
                            else if (evt.data.action === 'NS_EMBED_PAUSE') {
                                const elementPlayer = document.getElementById('vjs_video_3');
                                elementPlayer && elementPlayer.player && elementPlayer.player.pause();
                            }
                            // NS_EMBED_MUTE
                            else if (evt.data.action === 'NS_EMBED_MUTE') {
                                const muteBtn = document.querySelector(".vjs-mute-control:not(.vjs-vol-0)");
                                muteBtn && muteBtn.click();
                            }
                            // NS_EMBED_UNMUTE
                            else if (evt.data.action === 'NS_EMBED_UNMUTE') {
                                const muteBtn = document.querySelector(".vjs-mute-control.vjs-vol-0");
                                muteBtn && muteBtn.click();
                            }
                        }
                    }
                }"]

